effect.shader:
vec4 u_xlat0;
bvec4 u_xlatb0;
vec4 u_xlat1;
bool u_xlatb1;
vec4 u_xlat2;
float u_xlat4;
float u_xlat7;
void main()
{
    u_xlat0.x = _tex_angle * 0.0174532998;
    u_xlat1.x = cos(u_xlat0.x);
    u_xlat0.x = sin(u_xlat0.x);
    u_xlat2.z = u_xlat0.x;
    u_xlat2.y = u_xlat1.x;
    u_xlat2.x = (-u_xlat0.x);
    u_xlat0.y = dot(acScreenNorm.xy, u_xlat2.xy);
    u_xlat0.x = dot(acScreenNorm.xy, u_xlat2.yz);
    u_xlat0.xy = u_xlat0.xy + vec2(-0.700999975, -0.270000011);
    u_xlat0.xy = u_xlat0.xy * _tex_scale.xy + vec2(0.700999975, 0.270000011);
    u_xlat0.xy = u_xlat0.xy + (-_tex_offset.xy);
    u_xlat1 = texture(inputImg, u_xlat0.xy);
    u_xlatb0.zw = greaterThanEqual(u_xlat0.xxxy, vec4(0.0, 0.0, 0.0, 0.0)).zw;
    u_xlat0.xy = (-u_xlat0.xy) + vec2(1.0, 1.0);
    u_xlatb0.xy = greaterThanEqual(u_xlat0.xyxx, vec4(0.0, 0.0, 0.0, 0.0)).xy;
    u_xlat0.x = u_xlatb0.x ? float(1.0) : 0.0;
    u_xlat0.y = u_xlatb0.y ? float(1.0) : 0.0;
    u_xlat0.z = u_xlatb0.z ? float(1.0) : 0.0;
    u_xlat0.w = u_xlatb0.w ? float(1.0) : 0.0;
;
    u_xlat1 = u_xlat0.zzzz * u_xlat1;
    u_xlat1 = u_xlat0.xxxx * u_xlat1;
    u_xlat1 = u_xlat0.wwww * u_xlat1;
    u_xlat0 = u_xlat0.yyyy * u_xlat1;
    u_xlatb1 = 0<int(_invert_y);
    u_xlat4 = (-acScreenNorm.y) + 1.0;
    u_xlat1.y = (u_xlatb1) ? u_xlat4 : acScreenNorm.y;
    u_xlat1.x = acScreenNorm.x;
    u_xlat7 = texture(mask, u_xlat1.xy).x;
    u_xlat2 = texture(tex_map, u_xlat1.xy);
    u_xlat0 = u_xlat0 * vec4(u_xlat7);
    u_xlat1.x = (-u_xlat7) + 1.0;
    fragColor = u_xlat2 * u_xlat1.xxxx + u_xlat0;
    return;
}
